/**
 * What a sliced file shows about itself beyond its numbers: the picture the
 * slicer drew of the plate, and when it was sliced (CG, 22 Oct: "help me by
 * designing the parts to be more recognizable ... I'm pretty sure that the
 * data in the gcodes identifies when the part was printed").
 *
 * It does not, quite. A slicer writes when the file was MADE -- PrusaSlicer's
 * "Produced on" / "generated by ... on", a 3MF's CreationDate -- and nothing
 * on the printer writes back into the file. So this reads the sliced date
 * and says so; the printed date is the one recorded with the print.
 *
 * Thumbnails: PrusaSlicer embeds PNG, JPG or QOI previews (bgcode blocks of
 * type 5; "; thumbnail begin" base64 in plain G-code); Bambu and Orca put a
 * plate_N.png in the 3MF. The largest PNG/JPG no wider than 480 is kept; a
 * QOI-only file is converted where the platform can draw (the app can).
 */
import type { SliceFileLike } from './sliceImport'
import { inflateZlib, unzip } from './sliceImport'

export interface FileExtras {
  /** A data: URL, or null when the file has no picture we can show. */
  thumbnail: string | null
  /** When the file was sliced, ISO, or null. */
  slicedAt: string | null
}

interface Thumb {
  fmt: 'png' | 'jpg' | 'qoi'
  w: number
  bytes: Uint8Array
}

export async function fileExtras(file: SliceFileLike): Promise<FileExtras> {
  const name = file.name || ''
  try {
    if (/\.bgcode$/i.test(name)) return await fromBgcode(new Uint8Array(await file.arrayBuffer()))
    if (/\.3mf$/i.test(name)) return await from3mf(await file.arrayBuffer())
    if (/\.(gcode|gco|g)$/i.test(name)) return await fromGcode(await file.text())
  } catch {
    // A picture is a nicety; a file that will not give one is still a file.
  }
  return { thumbnail: null, slicedAt: null }
}

/** "2026-09-15 at 18:08:06 UTC" (PrusaSlicer) -> ISO. */
export function slicedDate(text: string): string | null {
  const m = /(\d{4}-\d{2}-\d{2})(?:\s+at\s+|[T\s])(\d{2}:\d{2}(?::\d{2})?)/.exec(text)
  if (m) return `${m[1]}T${m[2].length === 5 ? `${m[2]}:00` : m[2]}Z`
  const d = /(\d{4}-\d{2}-\d{2})/.exec(text)
  return d ? `${d[1]}T00:00:00Z` : null
}

async function fromBgcode(u8: Uint8Array): Promise<FileExtras> {
  const dv = new DataView(u8.buffer, u8.byteOffset, u8.byteLength)
  const N = u8.length
  if (N < 10 || String.fromCharCode(...u8.subarray(0, 4)) !== 'GCDE') return { thumbnail: null, slicedAt: null }
  const checksumType = dv.getUint16(8, true)
  const thumbs: Thumb[] = []
  let slicedAt: string | null = null
  let off = 10
  while (off + 8 <= N) {
    const type = dv.getUint16(off, true)
    const comp = dv.getUint16(off + 2, true)
    const usize = dv.getUint32(off + 4, true)
    off += 8
    let csize = usize
    if (comp !== 0) {
      csize = dv.getUint32(off, true)
      off += 4
    }
    if (type === 1) break
    const params = type === 5 ? 6 : 2
    const fmt = type === 5 ? dv.getUint16(off, true) : 0
    const w = type === 5 ? dv.getUint16(off + 2, true) : 0
    off += params
    const raw = u8.subarray(off, Math.min(N, off + csize))
    off += csize + (checksumType === 1 ? 4 : 0)
    const data = comp === 1 ? await inflateZlib(raw) : comp === 0 ? raw : null
    if (!data) continue
    if (type === 0) {
      const line = new TextDecoder().decode(data).split(/\r?\n/).find((l) => /^Produced on=/i.test(l))
      if (line) slicedAt = slicedDate(line)
    } else if (type === 5) thumbs.push({ fmt: fmt === 0 ? 'png' : fmt === 1 ? 'jpg' : 'qoi', w, bytes: data })
  }
  return { thumbnail: await best(thumbs), slicedAt }
}

async function fromGcode(src: string): Promise<FileExtras> {
  // Both live in the header; the moves can be 20 MB.
  const head = src.length > 4_000_000 ? src.slice(0, 4_000_000) : src
  const gen = /;\s*generated by [^\n]*?\bon\s+([^\n]+)/i.exec(head)
  const thumbs: Thumb[] = []
  const re = /;\s*thumbnail(?:_(JPG|QOI|PNG))?\s+begin\s+(\d+)x(\d+)[^\n]*\n([\s\S]*?);\s*thumbnail(?:_(?:JPG|QOI|PNG))?\s+end/gi
  for (const m of head.matchAll(re)) {
    const b64 = m[4].replace(/^;\s?/gm, '').replace(/\s+/g, '')
    const kind = (m[1] ?? 'PNG').toUpperCase()
    thumbs.push({ fmt: kind === 'JPG' ? 'jpg' : kind === 'QOI' ? 'qoi' : 'png', w: Number(m[2]), bytes: fromB64(b64) })
  }
  return { thumbnail: await best(thumbs), slicedAt: gen ? slicedDate(gen[1]) : null }
}

async function from3mf(buf: ArrayBuffer): Promise<FileExtras> {
  const z = await unzip(buf)
  const pic =
    z.names.find((n) => /Metadata\/plate_1\.png$/i.test(n)) ??
    z.names.find((n) => /Metadata\/plate_\d+\.png$/i.test(n)) ??
    z.names.find((n) => /thumbnail\.png$/i.test(n))
  const bytes = pic ? await z.read(pic) : null
  let slicedAt: string | null = null
  const model = z.names.find((n) => /3dmodel\.model$/i.test(n))
  if (model) {
    const raw = await z.read(model)
    const m = raw && /name="CreationDate"[^>]*>([^<]+)</i.exec(new TextDecoder().decode(raw.subarray(0, 200_000)))
    if (m) slicedAt = slicedDate(m[1])
  }
  return { thumbnail: bytes ? dataUrl('png', bytes) : null, slicedAt }
}

/** The largest PNG/JPG no wider than 480, else a QOI drawn as PNG. */
async function best(thumbs: Thumb[]): Promise<string | null> {
  const byW = (a: Thumb, b: Thumb) => b.w - a.w
  const direct = thumbs.filter((t) => t.fmt !== 'qoi' && t.w >= 64)
  const fit = direct.filter((t) => t.w <= 480).sort(byW)[0] ?? direct.sort((a, b) => a.w - b.w)[0]
  if (fit) return dataUrl(fit.fmt === 'jpg' ? 'jpg' : 'png', fit.bytes)
  const q = thumbs.filter((t) => t.fmt === 'qoi' && t.w >= 64).sort(byW)[0]
  return q ? qoiToPng(q.bytes) : null
}

function dataUrl(fmt: 'png' | 'jpg', bytes: Uint8Array): string {
  return `data:image/${fmt === 'jpg' ? 'jpeg' : 'png'};base64,${toB64(bytes)}`
}

function toB64(u8: Uint8Array): string {
  let s = ''
  for (let i = 0; i < u8.length; i += 0x8000) s += String.fromCharCode(...u8.subarray(i, i + 0x8000))
  return btoa(s)
}

function fromB64(s: string): Uint8Array {
  const bin = atob(s)
  const out = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i)
  return out
}

/** QOI ("Quite OK Image") to RGBA -- the format Prusa printers' screens use. */
export function decodeQoi(b: Uint8Array): { w: number; h: number; rgba: Uint8ClampedArray<ArrayBuffer> } | null {
  if (b.length < 14 || b[0] !== 0x71 || b[1] !== 0x6f || b[2] !== 0x69 || b[3] !== 0x66) return null
  const w = ((b[4] << 24) | (b[5] << 16) | (b[6] << 8) | b[7]) >>> 0
  const h = ((b[8] << 24) | (b[9] << 16) | (b[10] << 8) | b[11]) >>> 0
  if (!w || !h || w * h > 4_000_000) return null
  const px = new Uint8ClampedArray(new ArrayBuffer(w * h * 4))
  const index = new Uint8Array(64 * 4)
  let r = 0, g = 0, bl = 0, a = 255
  let p = 14
  let run = 0
  for (let o = 0; o < px.length; o += 4) {
    if (run > 0) run--
    else if (p < b.length - 8) {
      const b1 = b[p++]
      if (b1 === 0xfe) {
        r = b[p++]; g = b[p++]; bl = b[p++]
      } else if (b1 === 0xff) {
        r = b[p++]; g = b[p++]; bl = b[p++]; a = b[p++]
      } else if ((b1 & 0xc0) === 0x00) {
        const i = (b1 & 0x3f) * 4
        r = index[i]; g = index[i + 1]; bl = index[i + 2]; a = index[i + 3]
      } else if ((b1 & 0xc0) === 0x40) {
        r = (r + ((b1 >> 4) & 0x03) - 2) & 0xff
        g = (g + ((b1 >> 2) & 0x03) - 2) & 0xff
        bl = (bl + (b1 & 0x03) - 2) & 0xff
      } else if ((b1 & 0xc0) === 0x80) {
        const b2 = b[p++]
        const vg = (b1 & 0x3f) - 32
        r = (r + vg - 8 + ((b2 >> 4) & 0x0f)) & 0xff
        g = (g + vg) & 0xff
        bl = (bl + vg - 8 + (b2 & 0x0f)) & 0xff
      } else run = b1 & 0x3f
      const hi = ((r * 3 + g * 5 + bl * 7 + a * 11) % 64) * 4
      index[hi] = r; index[hi + 1] = g; index[hi + 2] = bl; index[hi + 3] = a
    }
    px[o] = r; px[o + 1] = g; px[o + 2] = bl; px[o + 3] = a
  }
  return { w, h, rgba: px }
}

async function qoiToPng(bytes: Uint8Array): Promise<string | null> {
  const img = decodeQoi(bytes)
  if (!img || typeof document === 'undefined') return null
  const c = document.createElement('canvas')
  c.width = img.w
  c.height = img.h
  const ctx = c.getContext?.('2d')
  if (!ctx) return null
  ctx.putImageData(new ImageData(img.rgba, img.w, img.h), 0, 0)
  return c.toDataURL('image/png')
}
